#!/usr/bin/python3 -I
"""Fixed read-only proposal-state census. No apply/lock/file/unit/SQL action."""
import base64, hashlib, json, os, resource, signal, subprocess as SP, sys, time, types
from pathlib import Path
V5_SHA='7e878f987524dce2583b348964032af62491ce3cabcdc49adc359b36b7fc5bd4'
V5_B64=''
EXPECTED_SHA='57571c36ee93bab0baa6b992e9fd67ccd8620c1efba5079b3b3be1685ff2371c'
CONTEXT_BINDING={'path': '/tmp/pow-audit30-promotion-full-read-native-144000-v2.stdout', 'bytes': 32091, 'sha256': '6304338f8004b3af1b1425e047dac193b52106dd7f496ffa46c0f355c992a369'}
MAX_CHANNEL=65536
END=None
class ObserverInterrupted(RuntimeError):pass
class ObserverRefused(RuntimeError):pass

def need(v,s):
    if not v:raise ObserverRefused(s)
def canonical(v):return json.dumps(v,sort_keys=True,separators=(',',':')).encode()
def load_v5():
    raw=base64.b64decode(V5_B64,validate=True);need(hashlib.sha256(raw).hexdigest()==V5_SHA,'Frozen V5 source bytes')
    m=types.ModuleType('frozen_promotion_v5');m.__file__='<frozen-promotion-v5>';exec(compile(raw,m.__file__,'exec'),m.__dict__)
    # __name__ is not __main__; neither main(),execute(),apply_pair() is called.
    m.subprocess=types.SimpleNamespace(run=frozen_run,DEVNULL=SP.DEVNULL);return m

def run_child(argv,timeout):
    remaining=timeout if END is None else min(timeout,END-time.monotonic());need(remaining>0,'Whole observation deadline')
    p=SP.Popen(argv,env={'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','LC_ALL':'C'},stdin=SP.DEVNULL,stdout=SP.PIPE,stderr=SP.PIPE,start_new_session=True)
    try:
        out,err=p.communicate(timeout=remaining);need(len(out)<=MAX_CHANNEL and len(err)<=MAX_CHANNEL,'Fixed child channel cap')
        return SP.CompletedProcess(argv,p.returncode,out,err)
    except BaseException as first:
        # Preserve first failure through own-session kill/reap even on repeated signals.
        ns=(signal.SIGINT,signal.SIGTERM,signal.SIGHUP,signal.SIGALRM);old={n:signal.getsignal(n)for n in ns}
        for n in ns:signal.signal(n,signal.SIG_IGN)
        try:
            try:os.killpg(p.pid,signal.SIGKILL)
            except ProcessLookupError:pass
            try:p.wait(timeout=5)
            except BaseException as cleanup:raise ObserverRefused('Owned child cleanup refused; first='+type(first).__name__)from cleanup
        finally:
            for n,h in old.items():signal.signal(n,h)
        raise
    finally:
        for f in(p.stdout,p.stderr):
            if f is not None:f.close()

def frozen_run(argv,**kw):
    need(kw=={'env':{'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','LC_ALL':'C'},'stdin':SP.DEVNULL,'capture_output':True,'timeout':kw.get('timeout')},'Fixed child options')
    if argv==['/usr/bin/python3','-I','-B','/usr/local/sbin/proofofwork-retention-protection','--role','node']:
        need(kw['timeout']==20,'Checker20-second bound');return run_child(argv,20)
    need(isinstance(argv,list)and len(argv)>3 and argv[:2]==['/usr/bin/systemctl','show'],'Only fixed readonly children')
    unit=argv[2];need(unit in M.UNITS,'Fixed ten units');need(argv==['/usr/bin/systemctl','show',unit]+[x for k in M.PROPERTIES_BY_UNIT[unit]for x in('-p',k)] and kw['timeout']==5,'Exact per-unit profile')
    return run_child(argv,5)

def validate_request(v):
    need(isinstance(v,dict)and set(v)=={'schema','contextBinding','expected','productionActionApproved'}and v['schema']=='pow-audit30-coupled-promotion-state-observer-request-v1'and v['productionActionApproved']is False,'Closed readonly request')
    need(v['contextBinding']==CONTEXT_BINDING and hashlib.sha256(canonical(v['expected'])).hexdigest()==EXPECTED_SHA,'Exact current2 public context binding')
    e=v['expected'];need(set(e)=={'files','mask','units','backupLockMetadata'} and set(e['files'])==set(map(str,(M.PIN,M.CHECKER)+M.STATIC))and set(e['units'])==set(M.UNITS),'Fixed expected fields')
    for n,row in e['units'].items():
        expected=set(M.PROPERTIES_BY_UNIT[n]);missing={'UnitFileState'} if n in M.LIVE+(M.BACKUP_SERVICE,)else set()
        need(set(row)==expected-missing and all(isinstance(x,str)for x in row.values()),'Exact known per-unit fields; new UnitFileState must be observed')
    return e

def idle(row):
    need(row['LoadState']=='loaded'and row['UnitFileState']=='static'and row['MainPID']=='0'and (row['ActiveState'],row['SubState'])in(('inactive','dead'),('failed','failed')),'Fresh monitor must be static and idle')

def states_check(actual,expected):
    need(set(actual)==set(expected)==set(M.UNITS),'Ten actual units')
    for name,row in actual.items():
        need(set(row)==set(M.PROPERTIES_BY_UNIT[name])and all(isinstance(v,str)for v in row.values()),'Actual per-unit profile')
        if name==M.MONITOR:
            need(all(row[k]==expected[name][k]for k in('LoadState','UnitFileState')),'Fixed monitor authority');idle(row)
        else:need(all(row[k]==v for k,v in expected[name].items()),'Fixed current2 unit identity drift')
    M.state_require(actual,actual)

def file_snapshot(expected):
    rows={}
    for p in(M.PIN,M.CHECKER)+M.STATIC:
        b,m=M.read(p,2097152,expected['files'][str(p)]['sha256']);need(m==expected['files'][str(p)]['metadata']and m['uid']==m['gid']==0,'Fixed file metadata/owner drift');rows[str(p)]={'metadata':m,'sha256':M.sha(b)}
    need(M.read(M.PIN,4096)[0]==M.OLD_PIN and rows[str(M.CHECKER)]['sha256']==M.OLD_CHECKER,'Original pin/checker required')
    mask=M.mask_state();need(mask==expected['mask'],'Exact prune mask identity')
    locks={}
    for p in(M.OPS,M.BACKUP_LOCK):
        b,m=M.read(p,4096);need(not b and m['nlink']==1,'Exact empty regular lock')
        if p==M.OPS:need(m['uid']==m['gid']==0 and m['mode']in(0o600,0o644),'Fixed root ops lock role/mode')
        else:need(m==expected['backupLockMetadata']and m['uid']==108 and m['gid']==112 and m['mode']==0o600,'Current2 backup lock identity')
        locks[str(p)]=m
    return {'files':rows,'mask':mask,'lockMetadata':locks}

def observe(request):
    expected=validate_request(request)
    before_states=M.unit_states();states_check(before_states,expected['units'])
    # The monitor tuple above is the sole fresh operational baseline; retain the
    # fixed LoadState/UnitFileState, require idle again at completion, report drift.
    before=file_snapshot(expected)
    # Frozen static/mask checker applies its independently pinned authority hashes.
    M.static_check({'static':{str(p):expected['files'][str(p)]for p in M.STATIC},'mask':expected['mask']})
    checker=frozen_run(['/usr/bin/python3','-I','-B',str(M.CHECKER),'--role','node'],env=M.ENV,stdin=SP.DEVNULL,capture_output=True,timeout=20)
    need(checker.returncode==1 and not checker.stderr,'Installed readonly checker exact outcome')
    projection=M.monitor_projection(json.loads(checker.stdout,object_pairs_hook=M.pairs));digest=M.sha(canonical(projection))
    after=file_snapshot(expected);need(before==after,'File/mask/lock identity drift across checker')
    after_states=M.unit_states();states_check(after_states,expected['units'])
    for name in M.UNITS:
        if name!=M.MONITOR:need(before_states[name]==after_states[name],'Unit endpoint drift across checker')
    return {'schema':'pow-audit30-coupled-promotion-state-observation-v1','status':'passed-readonly-proposal-state','atUtc':M.utc(),'sourceV5Sha256':V5_SHA,'contextBinding':CONTEXT_BINDING,'installed':{str(p):after['files'][str(p)]['metadata']for p in(M.PIN,M.CHECKER)},'static':{str(p):after['files'][str(p)]for p in M.STATIC},'mask':after['mask'],'lockMetadata':after['lockMetadata'],'units':after_states,'filesBeforeAfterEqual':True,'allFiveAndNonMonitorUnitEndpointsEqual':True,'originalPinCheckerBytesUnchanged':True,'expectedMonitorProjectionSha256':digest,'monitorProjection':projection,'monitorOperationalBefore':before_states[M.MONITOR],'monitorOperationalAfter':after_states[M.MONITOR],'monitorOperationalTupleUnchanged':before_states[M.MONITOR]==after_states[M.MONITOR],'knownHeldAbsencesUnresolved':18,'humanApprovalCreated':False,'promotionPerformed':False,'backupDeleted':False,'productionMutation':False,'recoveryActivated':False,'qualification':'Fixed readonly metadata/projection only. UnitFileState omissions were measured, never defaulted; periodic monitor operational endpoints are separately observed. No lock acquired or file/unit/SQL/backup action; no continuous-reader, recovery-capacity or deletion certificate.'}

def main():
    global END,M
    need(sys.flags.isolated and sys.dont_write_bytecode and os.geteuid()==os.getegid()==0,'Isolated root -I -B required');need(len(sys.argv)==1,'No free arguments')
    resource.setrlimit(resource.RLIMIT_AS,(256*1024**2,256*1024**2));resource.setrlimit(resource.RLIMIT_CPU,(30,30))
    ns=(signal.SIGINT,signal.SIGTERM,signal.SIGHUP,signal.SIGALRM);old={n:signal.getsignal(n)for n in ns};END=time.monotonic()+60
    def interrupted(n,_f):raise ObserverInterrupted('Fixed observation signal '+str(n))
    for n in ns:signal.signal(n,interrupted)
    signal.setitimer(signal.ITIMER_REAL,60)
    try:
        M=load_v5();b=sys.stdin.buffer.read(32769);need(len(b)<=32768,'Bounded request');v=json.loads(b,object_pairs_hook=M.pairs);result=observe(v);out=canonical(result)+b'\n';need(len(out)<=65536,'Public result channel cap');sys.stdout.buffer.write(out);sys.stdout.buffer.flush()
    finally:
        signal.setitimer(signal.ITIMER_REAL,0)
        for n,h in old.items():signal.signal(n,h)
if __name__=='__main__':main()
